vec3 palette(float t) {
    vec3 a = vec3(0.8, 0.5, 0.4);
    vec3 b = vec3(0.2, 0.4, 0.2);
    vec3 c = vec3(2.0, 1.0, 1.0);
    vec3 d = vec3(0.40, 0.20, 0.44);

    return a + b*cos(6.28318*(c*t+d));
}

float crossShape(vec2 uv, float thickness) {
    // Main vertical beam
    float vertical = smoothstep(thickness, 0.0, abs(uv.x));
    // Main horizontal beam
    float horizontal = smoothstep(thickness, 0.0, abs(uv.y));

    // Five diagonal beams for enhanced Byzantine style
    float angle = 2.0 * 3.14159 / 5.0; // Angle for pentagonal symmetry
    float diag1 = smoothstep(thickness*0.5, 0.0, abs(uv.x * cos(angle) - uv.y * sin(angle)));
    float diag2 = smoothstep(thickness*0.5, 0.0, abs(uv.x * cos(2.0*angle) - uv.y * sin(2.0*angle)));
    float diag3 = smoothstep(thickness*0.5, 0.0, abs(uv.x * cos(3.0*angle) - uv.y * sin(3.0*angle)));
    float diag4 = smoothstep(thickness*0.5, 0.0, abs(uv.x * cos(4.0*angle) - uv.y * sin(4.0*angle)));
    float diag5 = smoothstep(thickness*0.5, 0.0, abs(uv.x * cos(5.0*angle) - uv.y * sin(5.0*angle)));

    return max(max(vertical, horizontal), 
              max(max(diag1, diag2), 
                  max(max(diag3, diag4), diag5)));
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord * 2.0 - iResolution.xy) / iResolution.y;
    vec2 uv0 = uv;
    vec3 finalColor = vec3(0.0);

    float angle = iTime * 0.44;
    mat2 rot = mat2(cos(angle), -sin(angle),
                   sin(angle), cos(angle));
    uv = rot * uv;

    for (float i = 0.0; i < 5.0; i++) {  // Changed to 5 iterations
        vec2 uv_layer = uv * (0.010 + i * 1.1);
        float cross = crossShape(uv_layer, 0.1);
        float d = cross * exp(-length(uv0));
        vec3 col = palette(length(uv0) + i*.4 + iTime*.4);

        d = sin(d*4. + iTime)/8.;
        d = abs(d);
        d = pow(0.01 / d, 0.76);

        finalColor += col * d;
    }

    float centerGlow = exp(-length(uv0) * 2.0);
    finalColor += vec3(0.40, 0.40, 0.40) * centerGlow;
    finalColor *= 1.0 + 0.2 * sin(iTime * 2.0);

    fragColor = vec4(finalColor, 1.0);
}
